package studio.jiayu.neo;
import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.util.AtomicFile;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.UUID;

/** Explicit, user-confirmed IPC. It returns results, never provider credentials. */
public class IntegrationActivity extends Activity {
 static volatile boolean busy=false;
 static final Object STORE_LOCK=new Object();
 boolean running;String caller;
 @Override public void onCreate(Bundle b){super.onCreate(b);caller=getCallingPackage();if(caller==null){fail("此接口需要由 App 通过 startActivityForResult 调用");return;}try{String action=getIntent().getAction();if("studio.jiayu.neo.DEBUG_REPORT".equals(action))receiveReport();else if("studio.jiayu.neo.AI_REQUEST".equals(action))askAi();else fail("未知接口");}catch(Exception e){fail(e.getMessage()==null?"接口数据无效":e.getMessage());}}
 static JSONObject load(Context c)throws Exception{return new JSONObject(new String(new AtomicFile(new File(c.getFilesDir(),"workspace.json")).readFully(),StandardCharsets.UTF_8));}
 static void save(Context c,JSONObject s)throws Exception{AtomicFile a=new AtomicFile(new File(c.getFilesDir(),"workspace.json"));FileOutputStream f=a.startWrite();try{f.write(s.toString().getBytes(StandardCharsets.UTF_8));a.finishWrite(f);}catch(Exception e){a.failWrite(f);throw e;}}
 static JSONObject project(JSONObject s,String id)throws Exception{JSONArray a=s.getJSONArray("projects");for(int i=0;i<a.length();i++)if(a.getJSONObject(i).optString("id").equals(id))return a.getJSONObject(i);throw new Exception("找不到对应本地项目，请先导入或关联项目");}
 static JSONObject cleanReport(String raw)throws Exception{if(raw==null||raw.length()>64000)throw new Exception("调试报告为空或超过 64KB");JSONObject d=new JSONObject(raw);if(!"neo-debug/1".equals(d.optString("schema")))throw new Exception("不支持的调试报告格式");String id=d.getString("projectId");if(id.length()>100)throw new Exception("项目标识无效");JSONObject r=new JSONObject().put("schema","neo-debug/1").put("projectId",id).put("appId",d.optString("appId").substring(0,Math.min(160,d.optString("appId").length()))).put("version",d.optString("version")).put("time",d.optLong("time"));for(String key:new String[]{"events","tests"}){JSONArray list=d.optJSONArray(key);if(list==null)list=new JSONArray();if(list.length()>200)throw new Exception("报告条目过多");r.put(key,list);}String text=r.toString().replaceAll("(?i)(sk-[A-Za-z0-9_-]{12,}|Bearer\\s+[A-Za-z0-9._-]+)","[已隐藏密钥]");return new JSONObject(text);}
 static void storeReport(Context c,JSONObject report,String source)throws Exception{synchronized(STORE_LOCK){JSONObject s=load(c),p=project(s,report.getString("projectId"));JSONArray a=p.optJSONArray("debugReports");if(a==null){a=new JSONArray();p.put("debugReports",a);}while(a.length()>=20)a.remove(0);report.put("receivedAt",System.currentTimeMillis()).put("senderPackage",source);a.put(report);p.put("updated",System.currentTimeMillis());save(c,s);}}
 void receiveReport()throws Exception{if(MainActivity.instance!=null&&MainActivity.instance.active!=null){fail("请等待工作台当前请求结束再回传报告");return;}JSONObject r=cleanReport(getIntent().getStringExtra("report"));JSONObject p=project(load(this),r.getString("projectId"));String declared=r.optString("appId");new AlertDialog.Builder(this).setTitle("接收调试报告 · "+p.optString("name")).setMessage("系统调用方："+caller+"\n报告声明："+declared+"\n\n"+r.toString(2)).setPositiveButton("导入项目",(d,n)->{try{storeReport(this,r,caller);setResult(RESULT_OK);finish();}catch(Exception e){fail("报告保存失败");}}).setNegativeButton("取消",(d,n)->finish()).setOnCancelListener(d->finish()).show();}
 void askAi()throws Exception{if(!getSharedPreferences("ui",0).getBoolean("aiAssistantEnabled",true))throw new Exception("AI助手已关闭，请在 StepX Neo Studio 开启");if(busy||(MainActivity.instance!=null&&MainActivity.instance.active!=null)){fail("工作台已有 AI 请求，请稍后重试");return;}String id=getIntent().getStringExtra("projectId"),prompt=getIntent().getStringExtra("prompt");if(prompt==null||prompt.trim().isEmpty()||prompt.length()>4000)throw new Exception("提示词需为 1–4000 字符");JSONObject s=load(this),p=project(s,id);JSONArray profiles=s.getJSONArray("profiles");if(profiles.length()==0)throw new Exception("请先在 StepX Neo Studio 保存 API 配置");String[]labels=new String[profiles.length()];for(int i=0;i<labels.length;i++)labels[i]=profiles.getJSONObject(i).optString("name")+" · "+profiles.getJSONObject(i).optString("model");int[]selected={0};LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(32,12,32,12);TextView text=new TextView(this);text.setText("调用方："+caller+"\n项目："+p.optString("name")+"\n所选 API 模型会联网且可能计费；本地模型在手机运行。最大输出 1024 tokens。密钥不会交给此 App。\n\n"+prompt);box.addView(text);Spinner spinner=new Spinner(this);spinner.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels));box.addView(spinner);
  new AlertDialog.Builder(this).setTitle("允许这一次 AI 请求？").setView(box).setPositiveButton("发送本次请求",(d,n)->{try{JSONObject conf=new JSONObject(profiles.getJSONObject(spinner.getSelectedItemPosition()).toString());conf.put("maxTokens",Math.min(1024,conf.optInt("maxTokens",1024)));String key=conf.optString("protocol").equals("local")?"":new Vault(this).get(conf.getString("id"));if(!conf.optString("protocol").equals("local")&&key.isEmpty())throw new Exception("未保存密钥");runAi(id,prompt,conf,key);}catch(Exception e){fail(e.getMessage());}}).setNegativeButton("取消",(d,n)->finish()).setOnCancelListener(d->finish()).show();
 }
 void runAi(String id,String prompt,JSONObject profile,String key){busy=true;running=true;TextView text=new TextView(this);text.setPadding(32,80,32,32);text.setText("正在请求 "+profile.optString("name")+"…\n完成后自动回到调用 App。");setContentView(text);long time=System.currentTimeMillis();new Thread(()->{JSONObject result=null;String error=null;try{result=(profile.optString("protocol").equals("local")?new LocalAiClient(this):new ApiClient()).request(profile,key,new JSONArray().put(new JSONObject().put("role","user").put("content",prompt)),profile.optString("system","简洁回答。"),false);}catch(Exception e){error=e.getMessage();}try{synchronized(STORE_LOCK){JSONObject state=load(this);JSONObject log=new JSONObject().put("id",UUID.randomUUID().toString()).put("time",time).put("chatId","runtime:"+id).put("projectId",id).put("caller",caller).put("provider",profile.optString("name")).put("source",Usage.source(profile)).put("profileId",profile.optString("id")).put("model",result==null?profile.optString("model"):result.optString("model")).put("elapsedMs",System.currentTimeMillis()-time).put("status",result==null?"error":result.optBoolean("incomplete")?"incomplete":"ok").put("usage",result==null?new JSONObject().put("known",false):result.getJSONObject("usage"));state.getJSONArray("usage").put(log);JSONObject project=project(state,id);JSONArray h=project.optJSONArray("history");if(h==null){h=new JSONArray();project.put("history",h);}h.put(new JSONObject().put("time",System.currentTimeMillis()).put("type","runtime-api").put("text","App "+caller+" 发起经确认的 API 请求。"+(result==null?"失败，用量未知。":"已完成，Token 已入账。")));save(this,state);}}catch(Exception e){error="结果记录失败";}JSONObject reply=result==null?new JSONObject():result;try{if(error!=null)reply.put("error",error);}catch(Exception ignored){}String value=reply.toString();runOnUiThread(()->{busy=false;running=false;setResult(RESULT_OK,new Intent().putExtra("result",value));finish();});},"neo-app-api").start();}
 void fail(String msg){try{setResult(RESULT_OK,new Intent().putExtra("result",new JSONObject().put("error",msg).toString()));}catch(Exception ignored){}Toast.makeText(this,msg,Toast.LENGTH_LONG).show();finish();}
 @Override public void onBackPressed(){if(!running)super.onBackPressed();else Toast.makeText(this,"正在请求，请等待结果",Toast.LENGTH_SHORT).show();}
}
